1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: QuoteStep[];
16	};
17	
18	export type ScenarioResult = {
19	  results: unknown[];
20	};
21	
22	const PROCESSING_FEE = 5;
23	const FIRST_INSURANCE_SURCHARGE = 0.1;
24	
25	/** Premiums round up — in the MHPCO's favour. Float noise is discarded first. */
26	const roundUpToWholeG = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
27	
28	/** The item types the MHPCO will insure, and what each costs to cover. */
29	const BASE_PREMIUMS: Record<string, number | undefined> = {
30	  sword: 100,
31	  amulet: 60,
32	  staff: 80,
33	  potion: 40,
34	  rune: 25,
35	  moonstone: 25,
36	};
37	
38	/** Premium for a single item of this type. `undefined` for a type the MHPCO does not insure — rejecting those is not yet specified by a test. */
39	const unitPremiumFor = (type: string): number | undefined => BASE_PREMIUMS[type];
40	
41	const COMPONENT_BLOCK_SIZE = 3;
42	const COMPONENT_BLOCK_PREMIUM = 60;
43	
44	const countByType = (items: Item[]): Map<string, number> => {
45	  const counts = new Map<string, number>();
46	  for (const item of items) {
47	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
48	  }
49	  return counts;
50	};
51	
52	/** Alike components form a discounted block; everything else is priced per unit. */
53	const basePremiumForGroup = (type: string, count: number): number => {
54	  if (type === "rune" && count === COMPONENT_BLOCK_SIZE) return COMPONENT_BLOCK_PREMIUM;
55	  return count * (unitPremiumFor(type) ?? NaN);
56	};
57	
58	const policyBasePremium = (items: Item[]): number =>
59	  [...countByType(items)].reduce(
60	    (total, [type, count]) => total + basePremiumForGroup(type, count),
61	    0,
62	  );
63	
64	const quotePremium = (items: Item[]): number => {
65	  const policyBase = policyBasePremium(items);
66	  const withFirstInsurance = policyBase * (1 + FIRST_INSURANCE_SURCHARGE);
67	  const withProcessingFee = withFirstInsurance + PROCESSING_FEE;
68	  return roundUpToWholeG(withProcessingFee);
69	};
70	
71	export const runScenario = (scenario: Scenario): ScenarioResult => {
72	  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
73	};
