/** Component types that form discounted blocks. Only `rune` is demanded by a test so far. */
const BLOCK_FORMING_COMPONENTS = new Set(["rune"]);
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const formsBlock = (type: string, count: number): boolean =>
  BLOCK_FORMING_COMPONENTS.has(type) && count === COMPONENT_BLOCK_SIZE;
